CREATE TABLE IF NOT EXISTS "rol" ("id" INTEGER NOT NULL PRIMARY KEY, "nombre" VARCHAR(255) NOT NULL UNIQUE, "permisos" TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS "usuario" ("id" INTEGER NOT NULL PRIMARY KEY, "nombre" VARCHAR(255) NOT NULL, "correo" VARCHAR(255) NOT NULL UNIQUE, "contrasena" VARCHAR(255) NOT NULL, "rol_id" INTEGER NOT NULL, FOREIGN KEY ("rol_id") REFERENCES "rol" ("id"));
CREATE TABLE IF NOT EXISTS "autor" ("id" INTEGER NOT NULL PRIMARY KEY, "nombre" VARCHAR(255) NOT NULL, "biografia" TEXT NOT NULL, "usuario_id" INTEGER NOT NULL, FOREIGN KEY ("usuario_id") REFERENCES "usuario" ("id"));
CREATE TABLE IF NOT EXISTS "categoria" ("id" INTEGER NOT NULL PRIMARY KEY, "nombre" VARCHAR(255) NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS "articulo" ("id" INTEGER NOT NULL PRIMARY KEY, "titulo" VARCHAR(255) NOT NULL, "contenido" TEXT NOT NULL, "fecha_publicacion" DATE NOT NULL, "autor_id" INTEGER NOT NULL, "categoria_id" INTEGER NOT NULL, FOREIGN KEY ("autor_id") REFERENCES "autor" ("id"), FOREIGN KEY ("categoria_id") REFERENCES "categoria" ("id"));
